"""Generated bytecode must not weaken the frozen routing fixture pin (#10615).

These cases copy the fixture into scratch. They never write the real tree.
"""

from __future__ import annotations

import re
import shutil
from pathlib import Path

import pytest

from tests.review.test_model_catalog import FIXTURE, assert_frozen_routing_fixture_pinned

_PYC_NAME = "capture.cpython-312-pytest-9.1.1.pyc"


def _fixture_with_bytecode(tmp_path: Path) -> Path:
    root = tmp_path / "routing_baseline"
    shutil.copytree(FIXTURE, root, ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
    cache = root / "__pycache__"
    cache.mkdir()
    (cache / _PYC_NAME).write_bytes(b"generated-bytecode")
    return root


def _pin_failure(message: str) -> str:
    """Literal pytest.raises pattern for an assertion message."""
    return re.escape(message)


def test_generated_bytecode_does_not_weaken_literal_pins(tmp_path: Path) -> None:
    root = _fixture_with_bytecode(tmp_path)
    pyc = root / "__pycache__" / _PYC_NAME
    assert pyc.is_file() and not pyc.is_symlink()
    assert_frozen_routing_fixture_pinned(root)


def test_changed_pinned_bytes_still_fail(tmp_path: Path) -> None:
    root = _fixture_with_bytecode(tmp_path)
    assert_frozen_routing_fixture_pinned(root)
    capture = root / "capture.py"
    capture.write_bytes(capture.read_bytes() + b"\n")
    with pytest.raises(AssertionError, match=_pin_failure("capture.py pinned digest mismatch")):
        assert_frozen_routing_fixture_pinned(root)


def test_deleted_pinned_file_still_fails(tmp_path: Path) -> None:
    root = _fixture_with_bytecode(tmp_path)
    assert_frozen_routing_fixture_pinned(root)
    (root / "inputs.json").unlink()
    with pytest.raises(AssertionError, match=_pin_failure("pin membership missing=['inputs.json'] extra=[]")):
        assert_frozen_routing_fixture_pinned(root)


def test_added_non_cache_file_still_fails(tmp_path: Path) -> None:
    root = _fixture_with_bytecode(tmp_path)
    assert_frozen_routing_fixture_pinned(root)
    (root / "added.txt").write_text("not fixture content\n", encoding="utf-8")
    with pytest.raises(AssertionError, match=_pin_failure("pin membership missing=[] extra=['added.txt']")):
        assert_frozen_routing_fixture_pinned(root)


def test_non_pyc_inside_pycache_still_fails(tmp_path: Path) -> None:
    root = _fixture_with_bytecode(tmp_path)
    assert_frozen_routing_fixture_pinned(root)
    (root / "__pycache__" / "notes.txt").write_text("not bytecode\n", encoding="utf-8")
    with pytest.raises(
        AssertionError,
        match=_pin_failure("pin membership missing=[] extra=['__pycache__/notes.txt']"),
    ):
        assert_frozen_routing_fixture_pinned(root)


def test_pyc_outside_pycache_still_fails(tmp_path: Path) -> None:
    root = _fixture_with_bytecode(tmp_path)
    assert_frozen_routing_fixture_pinned(root)
    (root / "not-cache.pyc").write_bytes(b"not a cache")
    with pytest.raises(AssertionError, match=_pin_failure("pin membership missing=[] extra=['not-cache.pyc']")):
        assert_frozen_routing_fixture_pinned(root)


def test_symlink_pyc_inside_pycache_still_fails(tmp_path: Path) -> None:
    root = _fixture_with_bytecode(tmp_path)
    assert_frozen_routing_fixture_pinned(root)
    (root / "__pycache__" / "linked.pyc").symlink_to(_PYC_NAME)
    with pytest.raises(
        AssertionError,
        match=_pin_failure("pin membership missing=[] extra=['__pycache__/linked.pyc']"),
    ):
        assert_frozen_routing_fixture_pinned(root)


def test_nested_pycache_still_fails(tmp_path: Path) -> None:
    root = _fixture_with_bytecode(tmp_path)
    assert_frozen_routing_fixture_pinned(root)
    nested = root / "no-cli" / "__pycache__"
    nested.mkdir()
    (nested / "nested.pyc").write_bytes(b"nested")
    with pytest.raises(
        AssertionError,
        match=_pin_failure("pin membership missing=[] extra=['no-cli/__pycache__/nested.pyc']"),
    ):
        assert_frozen_routing_fixture_pinned(root)
